    errorcodes={'INVALID_REQUEST':('VALIDATION','DO_NOT_RETRY'),'UNAUTHENTICATED':('AUTHENTICATION','DO_NOT_RETRY'),'CSRF_INVALID':('AUTHENTICATION','DO_NOT_RETRY'),'REAUTHENTICATION_REQUIRED':('AUTHENTICATION','DO_NOT_RETRY'),'SESSION_NOT_FOUND':('VALIDATION','DO_NOT_RETRY'),'SESSION_ALREADY_REVOKED':('CONFLICT','DO_NOT_RETRY'),'SESSION_EXPIRED':('CONFLICT','DO_NOT_RETRY'),'SESSION_EPOCH_INVALIDATED':('CONFLICT','DO_NOT_RETRY'),'STATE_VERSION_CONFLICT':('CONFLICT','REFRESH_AND_RETRY_NEW_COMMAND'),'IDEMPOTENCY_CONFLICT':('CONFLICT','DO_NOT_RETRY'),'DEPENDENCY_UNAVAILABLE':('DEPENDENCY','RETRY_SAME_OPERATION'),'CURSOR_INVALID':('VALIDATION','DO_NOT_RETRY'),'CURSOR_QUERY_MISMATCH':('CONFLICT','DO_NOT_RETRY'),'SIDE_EFFECT_OUTCOME_UNKNOWN':('UNKNOWN','RECONCILE_THEN_RETRY')}
