     row=copy.deepcopy(next(x for x in records if x['operationId']==oid));idx=next(i for i,x in enumerate(records)if x['operationId']==oid);mut=oid.endswith('revoke');rq=copy.deepcopy(row['requestSchema']);rq['properties']['body']={'type':'null'};rq['properties']['query']={'type':'array','maxItems':0}if mut else obj({'cursor':nullable(U),'limit':nullable({**C,'not':{'const':'0'}})});rq['properties']['guards']['properties']={k:(C if k=='expectedStateVersion'and mut else v if k in ['idempotencyKey','clientRequestDigest'] else {'type':'null'})for k,v in rq['properties']['guards']['properties'].items()};
